pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.buyDrugs{value: 1 ether}();

        uint256 expectedBalance = (2 ether) - (4 * 1 ether / 100);
        assertEq(address(c).balance, expectedBalance);
    }
}
